import { useEffect, useId, useRef, useState } from "react";
import { DialogHeader } from "@kerfjs/ui/dialog-header";
import "@kerfjs/ui/layout.css";
import "./ItemDialog.css";

type Item = { id: string; title: string; summary: string; owner: string; updated: string };
export function ItemDialog({ open, items, onClose, onChoose }: {
  open: boolean; items: Item[]; onClose: () => void; onChoose: (id: string) => void;
}) {
  const dialog = useRef<HTMLDialogElement>(null);
  const titleId = useId();
  const summaryId = useId();
  const [selected, setSelected] = useState<string | null>(null);
  const item = items.find(i => i.id === selected) ?? items[0];
  useEffect(() => {
    const element = dialog.current;
    if (!element) return;
    const previous = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    if (open && !element.open) element.showModal();
    if (!open && element.open) element.close();
    return () => {
      if (element.open) element.close();
      if (open && previous?.isConnected) previous.focus();
    };
  }, [open]);
  return <dialog ref={dialog} className="kui-layout item-dialog" aria-labelledby={titleId}
    aria-describedby={summaryId} onCancel={e => { e.preventDefault(); onClose(); }}>
    <DialogHeader>
      <h2 id={titleId}>Choose an item</h2>
      <p id={summaryId}>Select an item to review its details, then confirm your choice.</p>
    </DialogHeader>
    <div className="dialog-body">
      <div className="master-detail">
        <fieldset className="item-list">
          <legend>Available items</legend>
          {items.length === 0 && <p>No items available.</p>}
          {items.map(entry => <label key={entry.id} className="item-choice">
            <input type="radio" name={titleId} checked={item?.id === entry.id}
              onChange={() => setSelected(entry.id)} />
            <span>{entry.title}</span>
          </label>)}
        </fieldset>
        <section className="item-detail" aria-label="Selected item details" aria-live="polite" aria-atomic="true">
          {item ? <>
            <h3>{item.title}</h3><p>{item.summary}</p>
            <dl><dt>Owner</dt><dd>{item.owner}</dd>
              <dt>Last updated</dt><dd>{item.updated}</dd></dl>
          </> : <p>Select an available item to see details.</p>}
        </section>
      </div>
    </div>
    <footer className="dialog-actions">
      <button type="button" onClick={onClose}>Cancel</button>
      <button type="button" disabled={!item} onClick={() => { if (item) onChoose(item.id); }}>Choose item</button>
    </footer>
  </dialog>;
}

