.item-dialog { width: min(52rem, calc(100vw - 2rem)); max-height: calc(100dvh - 2rem); padding: 0; overflow: hidden; }
.item-dialog[open] { display: flex; flex-direction: column; }
.item-dialog::backdrop { background: rgb(0 0 0 / .45); }
.dialog-body { flex: 1; min-height: 0; overflow: auto; padding: var(--kui-dialog-padding, 1rem); }
.master-detail { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 2fr); gap: var(--kui-section-gap, 1rem); }
.item-list { min-width: 0; padding: 0; margin: 0; border: 0; }
.item-choice { display: flex; align-items: center; min-height: 2.75rem; gap: var(--kui-control-gap, .5rem); }
.item-detail { min-width: 0; overflow-wrap: anywhere; }
.item-detail dl { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: var(--kui-metadata-gap, .5rem); }
.item-detail dd { margin: 0; }
.dialog-actions { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: var(--kui-control-gap, .5rem); padding: var(--kui-dialog-padding, 1rem); }
.dialog-actions button { min-height: 2.75rem; }
.item-dialog :focus-visible { outline: 2px solid currentColor; outline-offset: 2px; }
@media (max-width: 36rem) { .master-detail { grid-template-columns: minmax(0, 1fr); } }
